/* ===== 👘 TRANG PHỤC ĐẠO THỂ (equipment/51-dao-the-outfit.js) =====
 * Khi nhân vật đã Hợp Đạo (Đạo Thể: HDAO.on()), ngoại hình 3 hệ (Chiến binh / Pháp sư / Cung thủ) được thay bằng bộ trang phục mới.
 * Ảnh gốc được tách nền, cắt thành các mảnh (thân+đầu, tay trên/dưới ×2, chân ×2, giáp vai) đúng cấu trúc bộ xương RIGD của engine,
 * nên khớp mọi hoạt ảnh: đi, bay/nhảy, vung kiếm, đâm thương, kéo cung, niệm phép (pháp sư vẫn lơ lửng, váy phấp phới).
 * Cách làm: bọc hero() ở lớp NGOÀI CÙNG (module này nằm cuối index.html): trong lúc vẽ, tạm đặt RIGI[cur] = bộ mảnh Đạo Thể rồi trả lại ngay.
 *   Không sửa engine, không đổi dữ liệu/save, không đụng các module khác.
 * - Chỉ áp dụng cho nhân vật CỦA MÌNH. Người chơi khác ở Làng Online và đối thủ Đấu Trường (mượn P/cur) vẫn vẽ như cũ.
 * - Y Phục ở Tiệm Thời Trang tạm ẩn khi mặc bộ này (lớp nhuộm/phụ kiện đó khớp theo ảnh gốc). Cánh/hào quang/mũ vẫn hiện.
 * - Ảnh chưa tải xong hoặc có lỗi → tự vẽ như cũ.
 * Tắt/bật khi chơi: window.DAOTHE_OUTFIT.enable=false|true. */
(function(){
'use strict';
if(typeof hero!=='function'||typeof RIGI==='undefined'||typeof HDAO==='undefined'||typeof PS==='undefined'||typeof CHR==='undefined')return;
var CF=window.DAOTHE_OUTFIT={enable:true};
var D=[{"W":253.9,"H":420,"A_S":[166.7,114.2],"A_E":[178.8,157.3],"A_H":[185.4,220.2],"B_S":[72.8,114.2],"B_E":[61.8,155.1],"B_H":[66.2,221.3],"pivL":[90.5,329.5],"pivR":[158.9,329.5],"Au":["",152.3,106.0,33.1,63.5],"Al":["",158.9,152.9,37.5,88.9],"Bu":["",46.4,106.0,46.9,60.7],"Bl":["",46.4,148.5,38.6,97.7],"LL":["",56.8,324.5,53.5,96.6],"LR":["",144.6,324.5,54.1,83.9],"sh":["",53.5,61.8,136.9,70.6],"base":["",-0.6,-1.1,209.7,397.9]},{"W":256.0,"H":420,"A_S":[191.6,103.6],"A_E":[212.3,165.1],"A_H":[221.5,201.4],"Au":["",175.5,97.8,38.5,79.4],"Al":["",193.9,162.8,35.7,52.9],"sh":["",159.9,85.2,34.5,35.7],"base":["",5.2,1.2,243.9,420.0]},{"W":195.5,"H":420,"A_S":[111.4,99.5],"A_E":[129.1,148.1],"A_H":[136.2,212.7],"B_S":[57.5,99.5],"B_E":[39.7,148.1],"B_H":[30.2,212.7],"pivL":[62.2,274.9],"pivR":[120.8,274.9],"Au":["",103.1,103.1,41.5,56.3],"Al":["",115.5,140.4,31.4,88.9],"Bu":["",24.3,103.1,41.5,56.3],"Bl":["",20.7,143.9,42.7,84.7],"LL":["",27.2,267.2,55.7,137.4],"LR":["",99.5,267.2,51.5,152.8],"sh":["",96.6,71.1,39.7,52.7],"base":["",22.5,-1.2,170.0,330.0]}];
function build(d){var r={};for(var k in d){var v=d[k];if(Array.isArray(v)&&typeof v[0]==='string'){var im=new Image();im.src='data:image/webp;base64,'+v[0];r[k]={im:im,x:v[1],y:v[2],w:v[3],h:v[4]}}else r[k]=v}return r}
var RS=D.map(build),OK=[];
function ready(i){if(OK[i])return true;var r=RS[i];if(!r)return false;for(var k in r){var v=r[k];if(v&&v.im&&!(v.im.complete&&v.im.naturalWidth>0))return false}return OK[i]=true}
/* Chỉ nhân vật của mình: người khác/đối thủ được vẽ bằng bản sao P (Làng Online: hp=1,mp=1; Đấu Trường: có maxMp) */
function own(){return typeof P==='object'&&P&&!('maxMp' in P)&&!(P.hp===1&&P.mp===1&&P.atkT===1)}
function active(){try{return CF.enable&&own()&&HDAO.on()&&ready(cur)}catch(e){return false}}
var _hero=hero;
hero=function(){
  if(!active())return _hero.apply(this,arguments);
  var ci=cur,old=RIGI[ci],fa=PS[ci]&&PS[ci].fa,eq=fa&&fa.eq,sy=eq&&eq.y;
  try{RIGI[ci]=RS[ci];if(sy)eq.y=0;return _hero.apply(this,arguments)}
  finally{RIGI[ci]=old;if(sy)eq.y=sy}
};
})();
